+	remote := strategy.ResolveCheckpointURL(ctx, "origin")
+	if remote == "" {
+		remote = "origin"
+	}
+
+	disconnected, err := strategy.IsV2MainDisconnected(ctx, repo, remote)
+	if err != nil {
+		return fmt.Errorf("could not check v2 /main ref state: %w", err)
+	}
+
+	w := cmd.OutOrStdout()
+
+	if !disconnected {
+		fmt.Fprintln(w, "✓ v2 /main ref: OK")
+		return nil
+	}
